        AtlasFieldBase fieldBase = new AtlasFieldBase();
        AtlasFieldBase.Child fieldChild = new AtlasFieldBase.Child();
        Map<String, Object> tokens = new Map<String, Object>();
        Map<String, Object> boundaries = new Map<String, Object>();
        for (Type token : new List<Type>{
            String.class,
            List<String>.class,
            Map<String, List<Integer>>.class
        }) {
            tokens.put(token.getName(), new List<String>{
                TokenFactory.create(token),
                baseValue.forward(token),
                derivedValue.forward(token),
                nestedValue.forward(token)
            });
            boundaries.put(token.getName(), new List<String>{
                publicValue.forward(token),
                protectedValue.forward(token),
                baseValue.local(token)
            });
        }
        Map<String, Object> payload = new Map<String, Object>{
            'sourceApi' => 62,
            'route' => 'named',
            'tokens' => tokens,
            'controls' => new List<String>{
                derivedValue.ownField(),
                derivedValue.explicitField(),
                nestedValue.ownField(),
                nestedValue.explicitField()
            },
            'boundaries' => boundaries,
            'fieldControls' => new List<String>{
                publicValue.ownField(),
                publicValue.explicitField(),
                protectedValue.ownField(),
                protectedValue.explicitField(),
                fieldBase.readImplicit(),
                fieldBase.readExplicit(),
                fieldChild.readImplicit(),
                fieldChild.readExplicit(),
                fieldChild.ownField(),
                fieldChild.explicitField()
            }
        };
        payload.remove('tokens');
        payload.remove('controls');
        System.assert(false, 'RECEIVER_PRECEDENCE_OBSERVATION|' + JSON.serialize(payload));
